\title{Polynomial-time additive-error estimation of output probabilities\\ for shallow quantum circuits}

\author[1]{\mbox{Matthew Coudron}}
\author[1, 2]{\mbox{Michael J. Gullans}}
\author[1]{\mbox{Jon Nelson}}
\author[1,3]{\authorcr\mbox{Joel Rajakumar}}
\author[1]{\mbox{Shi Jie Samuel Tan}}

\affil[1]{University of Maryland, College Park}
\affil[2]{QuEra Computing Inc.}
\affil[3]{University of California, Los Angeles}
\date{}
\maketitle
\begingroup
\renewcommand{\thefootnote}{}
\footnotetext{Corresponding authors:
\href{mailto:nelson1@umd.edu}{\texttt{nelson1@umd.edu}},
\href{mailto:jrajakum@ucla.edu}{\texttt{jrajakum@ucla.edu}},
