    \centering

    \caption{A cartoon of the Hamiltonian learning problem from metastable states. A metastable state (orange gradient) lies in a double well, depicting a toy model of the free energy landscape of low temperature, 2D Ising model configurations of average magnetization $x$ (black curve). The learning algorithm guesses a Hamiltonian, and attempts to ``fit'' to the free-energy landscape (blue curve), by checking if the sampled state is also metastable w.r.t. the guess. See \cref{question:triangle}.}
    \label{fig:dw-ising}
\end{figure}

